INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0a9177e0-e09d-4a67-9496-5ccc59b3ebe8', '21feff02-016d-46e2-bb9d-c27495133b1b', '81. óra: Százalékszámítás', '1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "dc7f4cb4-5167-429e-b070-8eba986f074d", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "43fdd425-b0ad-46be-ae77-9d493589396e", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "98d735c5-66cf-4c97-813b-73a758b6699c", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "68c3ae85-6231-4396-9402-640b441896c5", "text": "100 egészet", "isCorrect": false}, {"id": "1eae19d0-8ff1-4dc5-a3dc-d6570b49e41c", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "8231b09d-e4b2-432e-a3e1-7542eafa56a2", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e8e27279-a1ba-4a3f-848d-c24830143ee6", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "47743319-4991-4f73-a4b1-7ff97844a039", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "ac8b4dc0-2eb9-4092-9ca4-893b16bf20f2", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "696baa34-b581-4848-93dd-bb34e1303bc7", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "55250083-d941-47f2-a3ef-2a94f8781933", "text": "Igaz", "isCorrect": true}, {"id": "4beb4349-8017-41fa-9951-7dc695bce346", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1661d421-50e1-4f19-8340-4a79e8f4a2be", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "8e64aaf6-f36c-4628-bd50-650e4b0540ff", "text": "Igaz", "isCorrect": true}, {"id": "274e5fa7-5f0b-4d23-adc7-77afa313ae37", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('748fd57d-abcf-41cf-8897-11e2a8f5ec2c', '21feff02-016d-46e2-bb9d-c27495133b1b', '82. óra: A százalékszámítás gyakorlása', 'Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "2f5e5b29-252a-437f-a2d6-6799a380dffc", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "819714f3-447a-4cba-8762-ab7d2dbb0921", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "5bf26f15-3ef4-4cb8-98d5-32903f737045", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "dce81468-b4e2-433d-a47c-efc81ef5469a", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "888214c0-a140-4e3b-8fd3-14d00e8003bf", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "76c23fd9-455c-426a-976b-9a4e19169c1a", "text": "Igaz", "isCorrect": true}, {"id": "658e2974-8c9b-47b8-8ae0-0c656697e63d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4883cc9c-c024-4b80-9fc4-967367878b4b", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "973a8d63-e133-4145-803b-9c378d5d603e", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('09e1f2c3-dcbe-459a-b97b-a7d0998526b2', '21feff02-016d-46e2-bb9d-c27495133b1b', '83. óra: Feladatmegoldás', 'Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f7e367f5-7cf3-481e-bdea-45e35d1b9d9c", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "45ef401f-cc2b-408c-b3a8-29dfe5659162", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "a39cb01c-6301-4e8d-871d-9c272eb1af93", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "e4f75b82-8393-4bb9-ad21-2636a19ae7f9", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "22ae9974-3107-4a02-9ddc-f6e025d5e779", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "ec70f15f-2b46-4fe6-bcb9-451bf1246d56", "text": "Igaz", "isCorrect": true}, {"id": "37e67985-19ff-4234-9888-85c6d85521a1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d97fa74d-f12c-499e-ae6f-605e9f9fd196", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "78c56621-3dd5-4286-9f86-e6ddc6d6b130", "text": "Igaz", "isCorrect": true}, {"id": "d33b2c81-15a5-4efe-bf28-b2432b7270cf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9d632c75-ff04-4b2c-9a87-be3b4f7f7efb", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('735b0d6d-7638-4d5e-8774-5f2520711fb9', '21feff02-016d-46e2-bb9d-c27495133b1b', '84. óra: Feladatmegoldás II.', 'Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "991959e3-558d-4f0c-ba19-7319bf6e306a", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "e3a9bbbd-af11-4bf2-a941-bb9d47dfbf6d", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "29bfa0d0-f872-49db-ad48-d25f27595e49", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "b09c958d-a2f6-450b-9877-7ec278dfa570", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "8102841e-dac5-4780-ac6f-d667b593ca6c", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "02298130-bcd8-4554-a0d9-dfd3cd0202e0", "text": "Igaz", "isCorrect": false}, {"id": "1246c5b6-b661-42ee-8094-4171d37ee5be", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "88a6473e-faa9-4d7c-ab94-e4465cf18946", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "2ab15010-667a-4ba8-8619-03a94e7f5816", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "e97228d4-030c-40e1-b110-f32488b135dd", "text": "Igaz", "isCorrect": true}, {"id": "b489a16d-02a9-418a-9fca-952d519d1dce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('09bff110-34e9-467f-a449-f2a25c53baa6', '21feff02-016d-46e2-bb9d-c27495133b1b', '85. óra: Projektóra', 'Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8d3d6b3b-40c3-4460-a49a-e962ad1da298", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "ef8cbe46-9a51-45b3-b96a-5862ce01727f", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "9114109e-d8cf-437b-b1b7-94efc2ad9747", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "1bec7504-c658-404e-9e5f-b863d21d3bf4", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "c66ea399-de76-4c4a-8418-38265dff806d", "text": "Igaz", "isCorrect": true}, {"id": "dcbcb4bd-7d2e-4ed1-be75-1dca3d85026b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8a0730ee-d39d-48fe-a617-86dd85c36447", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "f08f3042-57fc-44cb-96be-bbc0f9852424", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "8561af55-e28c-4898-8685-68fa9d6066ed", "text": "Igaz", "isCorrect": true}, {"id": "5f3efba0-ab32-4574-91bb-a1fcff99e3a5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "535bfaf9-bd9d-4ae5-8490-ce075ae41852", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "9965e9bd-7fc8-404c-951f-1615365bb615", "text": "Igaz", "isCorrect": true}, {"id": "3011736e-469a-43f3-a5c1-1f23e6ef3be7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7539af88-31f2-4a35-ab26-7b543a90c54c', '21feff02-016d-46e2-bb9d-c27495133b1b', '86. óra: Nyitott mondatok', 'Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "eea4539d-b0ae-40aa-bec2-76d91194c947", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "7b6a18c6-3440-4072-b642-c990a92d3d78", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "bacb508c-6be7-4f15-8737-8cf73f3e9489", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "443e2f98-6f91-43df-89ec-aed86a650682", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "c0f48ecc-0df1-44ad-8b24-7137e8e70edb", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "764e61cb-50e8-4093-90cb-ffb08f8f338f", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4143e7a0-96ed-4796-a3b0-8bd140af0244", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "c860994e-fa89-4d19-86f3-8ca8c515c26f", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "cf9ba28a-944c-4a88-a66c-6ed4ccb8551f", "text": "Igaz", "isCorrect": true}, {"id": "67b4bc26-68cf-4099-bea3-627411f2d33e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e11df01d-a637-4d96-a494-d46bdb4df093", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "4129696e-0127-45af-abd6-f0dddaaf4aab", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "bce648a9-a4f7-48c3-b59d-2b0ab0c6b457", "text": "Igaz", "isCorrect": true}, {"id": "ce3db759-4b0a-42f2-9bbf-756c29e4c462", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c4dbb2e-f7d6-4bb2-862e-5b2ce9d8e569", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c185b63f-d080-4055-b429-910b0d00ec67', '21feff02-016d-46e2-bb9d-c27495133b1b', '87. óra: Feladatmegoldás: Nyitott mondatok', 'Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f3ec70af-5795-4223-8f6e-1b1b63eb27c3", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "f3f00a6a-e45e-4b80-9443-9cb03d4c70f8", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "dcfcc646-8790-4d0c-8b2b-f6c6827eb845", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "885885ed-e4b4-4e5c-9e86-92d75b38e426", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "a1e8dd4b-7dd7-4c0c-920e-8aefd0cfaf79", "text": "Igaz", "isCorrect": true}, {"id": "8326773b-b0be-402a-ad90-f4ca8ff97c2c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "958d7d68-9d6d-40cf-af76-2d9dde82c5f6", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "cbdb9034-8e3a-444f-ab42-0286ca72f423", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "ac50cc23-8b24-4ece-bcb4-0ecc845c763b", "text": "Igaz", "isCorrect": true}, {"id": "48a13789-0cc5-4d4c-8191-e784bb7515d1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "87ad4fa6-62f7-4dc0-a3d1-f5fdfa51d96d", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a62e7bb6-ece5-42bf-a8f3-47562f5b73f5', '21feff02-016d-46e2-bb9d-c27495133b1b', '88. óra: Gyakorlóóra', 'Nyitott mondatok és műveleti sorrend gyakorlása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d2fbec66-75c7-4552-acdf-21d7faa1dffe", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "9edb562a-52ed-4e55-8214-9173b42a40b2", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "37c043ab-b67e-40ed-8f1e-383cb13573bb", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "7d1b00ac-26b9-4f5c-9a33-f49d83e2b0e2", "text": "Igaz", "isCorrect": true}, {"id": "30b024c1-9b81-4573-adc0-b4aac025a9b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eabab8cc-b194-47a5-bf7c-18dd0e74b28d", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "4cd8ac42-1f9a-4409-b6f0-5762c4140bc4", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "9b118b2f-0caf-494f-9582-874b5ad7eabf", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "f08da490-f8c0-4af9-ac68-ba9484dff8cd", "text": "Igaz", "isCorrect": true}, {"id": "ef4a3d71-7084-4a46-8e0a-9f5b8021f906", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a160a186-3af0-4650-bb1f-e825aedea911", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('df6acd0a-b0a7-4f11-9ebd-e04bfa522cd6', '21feff02-016d-46e2-bb9d-c27495133b1b', '89. óra: Szöveges feladatok', 'Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "bd714158-7d5f-4cf2-a1f6-69ebb41923db", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "cb72e902-dc3d-47cb-bb3c-6dc21869cc7d", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "6fc38a71-1ddd-4f08-9074-902bf09f0364", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "8fd35773-e659-4e6e-8862-77d3dca578a7", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "a0590f75-acf4-410e-a1ad-d3dd6719bba7", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "ca5832ec-286e-4f48-bef5-e1f066130989", "text": "Igaz", "isCorrect": true}, {"id": "ad5a1a1d-6d3d-485a-a040-188e74887fcc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ccfae4df-1ecb-45f4-8f58-3c26c79645cd", "text": "Ha a feladatban a ''kétszer annyi'' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "4a16ab0d-91c1-4f9c-9ba7-48e6df74f478", "text": "Igaz", "isCorrect": true}, {"id": "0ab27f4b-612c-4dc1-b9f3-81d983d62e4e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "60707757-79ca-430b-9976-01fd399582c5", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bea7566b-a26b-4925-9767-42691b648f2b', '21feff02-016d-46e2-bb9d-c27495133b1b', '90. óra: Gyakorlóóra', 'Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "de1bb226-0b2c-4bcb-ad16-712ee2c9c1c8", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "37672d3b-baf0-48bd-b5c0-9bf7f549e557", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "bfeb549d-bde0-4d18-9066-0da6479dfb16", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "eb6f2540-2b1e-445e-876d-66bb55523eca", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "6d65d0f7-0c06-4dfe-9ef4-a1a1dc1a114f", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "e2edae84-7846-46a3-99b3-6bb05ef694d6", "text": "Igaz", "isCorrect": true}, {"id": "953da9ca-4684-4051-9d07-0c089f68dbb4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "95da41df-cdab-4ee9-8ca6-ab5addb8590b", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "4c0738ae-bf6c-4f00-8c4c-38b05751f1d8", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "e44dbe10-a97b-4a47-bfce-d617fe1355f6", "text": "Igaz", "isCorrect": true}, {"id": "4835464b-9d0e-4689-934d-97599d5b157f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;